const xml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Math.round(value).toLocaleString();
export function waterBudgetGraphic(baseline,selected){
 const max=Math.max(baseline.demand,selected.demand,1);
 const row=(r,index)=>{const b=r.waterBalance;if(!b)return '';const rain=b.rain/max*100,irrigation=b.irrigation/max*100,gap=b.gap/max*100;return `<div class="budget-row"><div class="budget-row-heading"><span>${index===0?'Current practice':xml(r.name)}</span><strong>${number(r.demand)} <small>mm/year</small></strong></div><svg class="budget-bar" viewBox="0 0 100 8" preserveAspectRatio="none" role="img" aria-label="${xml(r.name)}: ${number(b.rain)} millimetres effective rain, ${number(b.irrigation)} assumed irrigation, ${number(b.gap)} unmet need"><defs><pattern id="gap-hatch-${index}" width="2" height="8" patternUnits="userSpaceOnUse"><rect width="2" height="8" fill="#b76f54"/><path d="M0 8L2 0" stroke="#ffffff66" stroke-width=".3"/></pattern></defs><rect width="100" height="8" rx="1" class="budget-track"/><rect width="${rain}" height="8" class="budget-rain"/><rect x="${rain}" width="${irrigation}" height="8" class="budget-irrigation"/><rect x="${rain+irrigation}" width="${gap}" height="8" fill="url(#gap-hatch-${index})"/></svg><div class="budget-row-detail"><span>${number(b.rain)} rain + ${number(b.irrigation)} irrigation</span><span class="${b.gap>0?'has-gap':'no-gap'}">${number(b.gap)} mm unmet</span></div></div>`};
 return `<p class="budget-scale">Shared scale: 0–${number(max)} mm/year</p>${row(baseline,0)}${row(selected,1)}`;
}
